#include <algorithm>
#include <cmath>
#include <cstdio>
#include <string>
#include <vector>

struct Point { double x, y; };

namespace
{
    double nice(double x, bool round)
    {
        const double e{ std::floor(std::log10(x)) };
        const double f{ x / std::pow(10.0, e) };
        double nf;
        if (round) nf = f < 1.5 ? 1 : f < 3 ? 2 : f < 7 ? 5 : 10;
        else nf = f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10;
        return nf * std::pow(10.0, e);
    }
}

std::vector<double> niceTicks(double lo, double hi, int maxTicks)
{
    if (hi <= lo) hi = lo + 1;
    const double range{ nice(hi - lo, false) };
    const double step{ nice(range / (maxTicks - 1), true) };
    const long long first{ static_cast<long long>(std::floor(lo / step + 1e-9)) };
    const long long last{ static_cast<long long>(std::ceil(hi / step - 1e-9)) };
    std::vector<double> ticks;
    for (long long k{ first }; k <= last; ++k) ticks.push_back(static_cast<double>(k) * step);
    return ticks;
}

std::string tickLabel(double v)
{
    char buffer[64];
    std::snprintf(buffer, sizeof(buffer), "%.6f", v);
    std::string s{ buffer };
    while (!s.empty() && s.back() == '0') s.pop_back();
    if (!s.empty() && s.back() == '.') s.pop_back();
    if (s == "-0") s = "0";
    return s;
}

class Chart
{
public:
    Chart(std::vector<Point> data, double width, double height, double margin)
        : m_data{ std::move(data) }, m_left{ margin }, m_top{ margin }, m_right{ width - margin }, m_bottom{ height - margin }
    {
        m_xLo = m_data.front().x;
        m_xHi = m_data.back().x;
        double yLo{ m_data.front().y }, yHi{ m_data.front().y };
        for (const Point& p : m_data) { yLo = std::min(yLo, p.y); yHi = std::max(yHi, p.y); }
        m_ticks = niceTicks(yLo, yHi, 6);
        m_yLo = m_ticks.front();
        m_yHi = m_ticks.back();
    }

    const std::vector<double>& yTicks() const { return m_ticks; }

    Point toScreen(Point p) const
    {
        const double x{ m_xHi == m_xLo ? (m_left + m_right) / 2 : m_left + (p.x - m_xLo) / (m_xHi - m_xLo) * (m_right - m_left) };
        const double y{ m_bottom - (p.y - m_yLo) / (m_yHi - m_yLo) * (m_bottom - m_top) };
        return { x, y };
    }

    Point toData(Point s) const
    {
        const double x{ m_xHi == m_xLo ? m_xLo : m_xLo + (s.x - m_left) / (m_right - m_left) * (m_xHi - m_xLo) };
        const double y{ m_yLo + (m_bottom - s.y) / (m_bottom - m_top) * (m_yHi - m_yLo) };
        return { x, y };
    }

    int nearestIndex(double screenX) const
    {
        const double x{ toData({ screenX, 0 }).x };
        const auto it{ std::lower_bound(m_data.begin(), m_data.end(), x, [](const Point& p, double v) { return p.x < v; }) };
        if (it == m_data.begin()) return 0;
        if (it == m_data.end()) return static_cast<int>(m_data.size()) - 1;
        const auto before{ std::prev(it) };
        return static_cast<int>((x - before->x <= it->x - x ? before : it) - m_data.begin());
    }

    std::vector<Point> polyline(double tolerance) const
    {
        std::vector<Point> screen;
        for (const Point& p : m_data) screen.push_back(toScreen(p));
        if (screen.size() < 3) return screen;
        std::vector<bool> keep(screen.size(), false);
        keep.front() = keep.back() = true;
        simplify(screen, 0, screen.size() - 1, tolerance, keep);
        std::vector<Point> out;
        for (std::size_t i{ 0 }; i < screen.size(); ++i) if (keep[i]) out.push_back(screen[i]);
        return out;
    }

private:
    static double distance(Point p, Point a, Point b)
    {
        const double dx{ b.x - a.x }, dy{ b.y - a.y };
        const double len{ std::sqrt(dx * dx + dy * dy) };
        if (len == 0) return std::hypot(p.x - a.x, p.y - a.y);
        return std::fabs((p.x - a.x) * dy - (p.y - a.y) * dx) / len;
    }

    static void simplify(const std::vector<Point>& pts, std::size_t a, std::size_t b, double tol, std::vector<bool>& keep)
    {
        if (b <= a + 1) return;
        double best{ -1 };
        std::size_t index{ a };
        for (std::size_t i{ a + 1 }; i < b; ++i)
        {
            const double d{ distance(pts[i], pts[a], pts[b]) };
            if (d > best) { best = d; index = i; }
        }
        if (best <= tol) return;
        keep[index] = true;
        simplify(pts, a, index, tol, keep);
        simplify(pts, index, b, tol, keep);
    }

    std::vector<Point> m_data;
    double m_left, m_top, m_right, m_bottom;
    double m_xLo{ 0 }, m_xHi{ 0 }, m_yLo{ 0 }, m_yHi{ 1 };
    std::vector<double> m_ticks;
};

unitTests:
std::vector<std::string> labels(const std::vector<double>& t) { std::vector<std::string> s; for (double v : t) s.push_back(tickLabel(v)); return s; }
using Labels = std::vector<std::string>;
bool nearP(Point p, double x, double y) { return std::fabs(p.x - x) < 1e-6 && std::fabs(p.y - y) < 1e-6; }
const std::vector<Point> data{ { 0, 0 }, { 2, 10 }, { 4, 20 }, { 6, 30 }, { 8, 95 }, { 10, 40 } };
TEST("nice ticks") {
    CHECK_EQ(labels(niceTicks(0, 97, 6)), (Labels{ "0", "20", "40", "60", "80", "100" }));
    CHECK_EQ(labels(niceTicks(-3.2, 7.9, 5)), (Labels{ "-5", "0", "5", "10" }));
    CHECK_EQ(labels(niceTicks(0.01, 0.034, 5)), (Labels{ "0.01", "0.02", "0.03", "0.04" }));
    CHECK_EQ(labels(niceTicks(1234, 5678, 6)), (Labels{ "1000", "2000", "3000", "4000", "5000", "6000" }));
    CHECK_EQ(labels(niceTicks(5, 5, 6)), (Labels{ "5", "5.2", "5.4", "5.6", "5.8", "6" }));
}
TEST("labels") { CHECK_EQ(tickLabel(-0.0), std::string("0")); CHECK_EQ(tickLabel(2.5), std::string("2.5")); CHECK_EQ(tickLabel(1e-7), std::string("0")); CHECK_EQ(tickLabel(100), std::string("100")); CHECK_EQ(tickLabel(-12.345), std::string("-12.345")); }
TEST("data and screen") {
    const Chart c{ data, 220, 120, 10 };
    CHECK_EQ(c.yTicks().size(), std::size_t{ 6 }); CHECK(nearP(c.toScreen({ 0, 0 }), 10, 110)); CHECK(nearP(c.toScreen({ 10, 100 }), 210, 10)); CHECK(nearP(c.toScreen({ 4, 20 }), 90, 90));
    CHECK(nearP(c.toData({ 90, 90 }), 4, 20)); CHECK(nearP(c.toData({ 110, 60 }), 5, 50));
}
TEST("nearest point") {
    const Chart c{ data, 220, 120, 10 };
    CHECK_EQ(c.nearestIndex(95), 2); CHECK_EQ(c.nearestIndex(100), 2); CHECK_EQ(c.nearestIndex(110), 2); CHECK_EQ(c.nearestIndex(111), 3);
    CHECK_EQ(c.nearestIndex(-50), 0); CHECK_EQ(c.nearestIndex(500), 5);
}
TEST("simplifying") {
    const Chart c{ data, 220, 120, 10 };
    const auto fine = c.polyline(1.0); CHECK_EQ(fine.size(), std::size_t{ 4 }); CHECK(nearP(fine[1], 130, 80)); CHECK(nearP(fine[2], 170, 15));
    const auto coarse = c.polyline(40.0); CHECK_EQ(coarse.size(), std::size_t{ 3 }); CHECK(nearP(coarse[1], 170, 15));
    CHECK_EQ(c.polyline(1000.0).size(), std::size_t{ 2 });
}
TEST("a single x value") { const Chart c{ { { 3, 1 }, { 3, 2 } }, 100, 100, 0 }; CHECK(nearP(c.toScreen({ 3, 1 }), 50, 100)); CHECK_EQ(c.nearestIndex(10), 0); }

